package com.opensync.gateway.ai;
import com.fasterxml.jackson.databind.*;import com.opensync.contracts.*;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(name="opensync.llm.provider",havingValue="openai")
public class OpenAiLlmClient implements LlmClient{
 private final RestClient client;private final ObjectMapper json;private final String model;
 public OpenAiLlmClient(ObjectMapper j,@Value("${opensync.llm.openai.base-url:https://api.openai.com/v1}") String url,@Value("${opensync.llm.openai.api-key:}") String key,@Value("${opensync.llm.openai.model:gpt-4.1-mini}") String model){if(key.isBlank())throw new IllegalStateException("OPENAI_API_KEY is required when LLM_PROVIDER=openai");var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofSeconds(3));f.setReadTimeout(Duration.ofSeconds(20));client=RestClient.builder().requestFactory(f).baseUrl(url).defaultHeader("Authorization","Bearer "+key).build();json=j;this.model=model;}
 public SchemaMappingSuggestion suggestMapping(JsonNode p,CanonicalSchema s){return call("Return only JSON matching SchemaMappingSuggestion. Allowed transformations: "+Arrays.toString(TransformationType.values())+". Canonical schema: "+s+". Partner sample: "+p,SchemaMappingSuggestion.class);}
 public FailureExplanation explainFailure(FailureContext c){return call("Explain this inventory failure without taking actions. Return only JSON: "+c,FailureExplanation.class);}
 private <T>T call(String prompt,Class<T> type){var body=Map.of("model",model,"messages",List.of(Map.of("role","system","content","You are a schema and failure analysis assistant. Never emit executable code."),Map.of("role","user","content",prompt)),"response_format",Map.of("type","json_object"));var response=client.post().uri("/chat/completions").body(body).retrieve().body(JsonNode.class);try{return json.readValue(response.at("/choices/0/message/content").asText(),type);}catch(Exception e){throw new IllegalStateException("Invalid structured LLM response",e);}}
}
